def get_events(calendar_name, start=None, end=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0061000" if __import__("os").path.isdir("./environment_mix/0061000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    cal_name = calendar_name

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, str) or not dt.strip():
            raise ValueError("datetime must be a non-empty string")
        s = dt.strip()
        # Allow trailing Z
        if s.endswith("Z"):
            s2 = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s2).replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                pass
        # Try as-is
        d = datetime.datetime.fromisoformat(s)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc)

    # Audit log (create if missing)
    audits = _load("audit.json")
    if not isinstance(audits, list):
        audits = []

    def _log_and_return(payload):
        nonlocal audits
        latency_ms = int((time.time() - t0) * 1000)
        audits.append({
            "ts": _now_iso(),
            "endpoint": "get_events",
            "status": status,
            "latency_ms": latency_ms,
            "meta": {"calendar_name": cal_name}
        })
        _save("audit.json", audits)
        return payload

    # Validate inputs
    if not isinstance(calendar_name, str) or not calendar_name.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "calendar_name must be a non-empty string"))

    if start is not None and (not isinstance(start, str) or not start.strip()):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "start must be a non-empty ISO 8601 datetime string when provided"))
    if end is not None and (not isinstance(end, str) or not end.strip()):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "end must be a non-empty ISO 8601 datetime string when provided"))

    try:
        start_dt = _parse_iso(start) if start is not None else None
        end_dt = _parse_iso(end) if end is not None else None
    except ValueError:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "start/end must be valid ISO 8601 datetimes"))

    if start_dt and end_dt and start_dt > end_dt:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid range: start occurs after end"))

    # Load calendars datastore
    store = _load("calendars.json")
    if not isinstance(store, dict):
        # If file empty/invalid, treat as no calendars configured
        store = {}

    if calendar_name not in store:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "calendar_name does not exist", calendar_name=calendar_name))

    evs = store.get(calendar_name) or []
    if not isinstance(evs, list):
        evs = []

    # Filter events that "fall within" provided range: overlap [start,end]
    out = []
    for e in evs:
        if not isinstance(e, dict):
            continue
        ds = e.get("dtstart")
        de = e.get("dtend")
        try:
            e_start = _parse_iso(ds) if isinstance(ds, str) else None
            e_end = _parse_iso(de) if isinstance(de, str) else None
        except ValueError:
            # Ignore malformed event rows rather than failing the whole request
            continue
        if e_start is None or e_end is None:
            continue

        if start_dt or end_dt:
            # overlap check
            if start_dt and e_end < start_dt:
                continue
            if end_dt and e_start > end_dt:
                continue
        out.append(e)

    # Sort by dtstart then uid for stable output
    def _key(e):
        try:
            return (e.get("dtstart") or "", e.get("uid") or "")
        except Exception:
            return ("", "")
    out.sort(key=_key)

    return _log_and_return({
        "calendar_name": calendar_name,
        "start": start,
        "end": end,
        "events": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None
    })

def find_events(calendar_name, summary_contains, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0061000" if __import__("os").path.isdir("./environment_mix/0061000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    cal_name = calendar_name

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    audits = _load("audit.json")
    if not isinstance(audits, list):
        audits = []

    def _log_and_return(payload):
        nonlocal audits
        latency_ms = int((time.time() - t0) * 1000)
        audits.append({
            "ts": _now_iso(),
            "endpoint": "find_events",
            "status": status,
            "latency_ms": latency_ms,
            "meta": {"calendar_name": cal_name}
        })
        _save("audit.json", audits)
        return payload

    # Validate inputs
    if not isinstance(calendar_name, str) or not calendar_name.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "calendar_name must be a non-empty string"))
    if not isinstance(summary_contains, str) or not summary_contains.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "summary_contains must be a non-empty string"))

    store = _load("calendars.json")
    if not isinstance(store, dict):
        store = {}

    if calendar_name not in store:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "calendar_name does not exist", calendar_name=calendar_name))

    needle = summary_contains.lower()
    evs = store.get(calendar_name) or []
    if not isinstance(evs, list):
        evs = []

    out = []
    for e in evs:
        if not isinstance(e, dict):
            continue
        s = e.get("summary", "")
        if isinstance(s, str) and needle in s.lower():
            out.append(e)

    # Stable sort
    out.sort(key=lambda e: ((e.get("dtstart") or ""), (e.get("uid") or "")))
    return _log_and_return({
        "calendar_name": calendar_name,
        "summary_contains": summary_contains,
        "events": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None
    })

def add_event(calendar_name, summary, dtstart, dtend, description="", location="", uid=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0061000" if __import__("os").path.isdir("./environment_mix/0061000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    cal_name = calendar_name

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if not isinstance(dt, str) or not dt.strip():
            raise ValueError("datetime must be a non-empty string")
        s = dt.strip()
        if s.endswith("Z"):
            s2 = s[:-1]
            d = datetime.datetime.fromisoformat(s2).replace(tzinfo=datetime.timezone.utc)
            return d
        d = datetime.datetime.fromisoformat(s)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc)

    audits = _load("audit.json")
    if not isinstance(audits, list):
        audits = []

    def _log_and_return(payload):
        nonlocal audits
        latency_ms = int((time.time() - t0) * 1000)
        audits.append({
            "ts": _now_iso(),
            "endpoint": "add_event",
            "status": status,
            "latency_ms": latency_ms,
            "meta": {"calendar_name": cal_name}
        })
        _save("audit.json", audits)
        return payload

    # Validate
    if not isinstance(calendar_name, str) or not calendar_name.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "calendar_name must be a non-empty string"))
    for field_name, val in [("summary", summary), ("dtstart", dtstart), ("dtend", dtend)]:
        if not isinstance(val, str) or not val.strip():
            status = "error"
            return _log_and_return(_err("VALIDATION_ERROR", f"{field_name} must be a non-empty string"))

    if description is not None and not isinstance(description, str):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "description must be a string when provided"))
    if location is not None and not isinstance(location, str):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "location must be a string when provided"))
    if uid is not None and (not isinstance(uid, str) or not uid.strip()):
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "uid must be a non-empty string when provided"))

    try:
        sdt = _parse_iso(dtstart)
        edt = _parse_iso(dtend)
    except ValueError:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "dtstart/dtend must be valid ISO 8601 datetimes"))
    if edt <= sdt:
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "dtend must be after dtstart"))

    store = _load("calendars.json")
    if not isinstance(store, dict):
        store = {}

    if calendar_name not in store:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "calendar does not exist", calendar_name=calendar_name))

    evs = store.get(calendar_name)
    if not isinstance(evs, list):
        evs = []
        store[calendar_name] = evs

    existing_uids = set()
    for e in evs:
        if isinstance(e, dict) and isinstance(e.get("uid"), str):
            existing_uids.add(e["uid"])

    if uid is not None:
        if uid in existing_uids:
            status = "error"
            return _log_and_return(_err("CONFLICT", "uid already exists in this calendar", uid=uid, calendar_name=calendar_name))
        new_uid = uid
    else:
        # Generate unique uid with service-like prefix
        # Ensure non-collision even across deletes
        base = int(time.time() * 1000)
        new_uid = f"evt-{base}"
        if new_uid in existing_uids:
            new_uid = f"evt-{base}-{random.randint(1000,9999)}"
        i = 0
        while new_uid in existing_uids and i < 50:
            i += 1
            new_uid = f"evt-{base}-{random.randint(10000,99999)}"
        if new_uid in existing_uids:
            status = "error"
            return _log_and_return(_err("CONFLICT", "could not allocate unique uid"))

    ev = {
        "uid": new_uid,
        "summary": summary,
        "dtstart": dtstart,
        "dtend": dtend,
        "description": description or "",
        "location": location or "",
        "attendees": [],
        "organizer": "",
        "recurrence": "",
        "status": "confirmed"
    }

    evs.append(ev)
    _save("calendars.json", store)

    return _log_and_return({
        "calendar_name": calendar_name,
        "uid": new_uid,
        "event": ev
    })

def delete_event(calendar_name, uid, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0061000" if __import__("os").path.isdir("./environment_mix/0061000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    cal_name = calendar_name

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    audits = _load("audit.json")
    if not isinstance(audits, list):
        audits = []

    def _log_and_return(payload):
        nonlocal audits
        latency_ms = int((time.time() - t0) * 1000)
        audits.append({
            "ts": _now_iso(),
            "endpoint": "delete_event",
            "status": status,
            "latency_ms": latency_ms,
            "meta": {"calendar_name": cal_name, "uid": uid}
        })
        _save("audit.json", audits)
        return payload

    # Validate
    if not isinstance(calendar_name, str) or not calendar_name.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "calendar_name must be a non-empty string"))
    if not isinstance(uid, str) or not uid.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "uid must be a non-empty string"))

    store = _load("calendars.json")
    if not isinstance(store, dict):
        store = {}

    if calendar_name not in store:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "calendar does not exist", calendar_name=calendar_name))

    evs = store.get(calendar_name)
    if not isinstance(evs, list):
        evs = []
        store[calendar_name] = evs

    idx = None
    for i, e in enumerate(evs):
        if isinstance(e, dict) and e.get("uid") == uid:
            idx = i
            break

    if idx is None:
        status = "error"
        return _log_and_return(_err("NOT_FOUND", "event not found in calendar", calendar_name=calendar_name, uid=uid))

    deleted_event = evs.pop(idx)
    _save("calendars.json", store)

    return _log_and_return({
        "calendar_name": calendar_name,
        "uid": uid,
        "deleted": True,
        "event": deleted_event
    })

def create_calendar(name, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0061000" if __import__("os").path.isdir("./environment_mix/0061000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    audits = _load("audit.json")
    if not isinstance(audits, list):
        audits = []

    def _log_and_return(payload):
        nonlocal audits
        latency_ms = int((time.time() - t0) * 1000)
        audits.append({
            "ts": _now_iso(),
            "endpoint": "create_calendar",
            "status": status,
            "latency_ms": latency_ms,
            "meta": {"name": name}
        })
        _save("audit.json", audits)
        return payload

    # Validate
    if not isinstance(name, str) or not name.strip():
        status = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "name must be a non-empty string"))

    cal_name = name.strip()

    store = _load("calendars.json")
    if not isinstance(store, dict):
        store = {}

    if cal_name in store:
        status = "error"
        return _log_and_return(_err("CONFLICT", "calendar with that name already exists", name=cal_name))

    store[cal_name] = []
    _save("calendars.json", store)

    return _log_and_return({
        "calendar": {"name": cal_name, "events": []}
    })
